def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    H, W = g.shape
    table = {1: 5, 2: 7}
    holes = components(g == bg)
    for comp in holes:
        if any(y == 0 or x == 0 or y == H - 1 or x == W - 1 for y, x in comp):
            continue  # open background, not an interior
        colour = table.get(len(comp), 7 if len(comp) > 1 else 5)
        for y, x in comp:
            out[y, x] = colour
        emit(out, f"Filled an enclosed hole of {len(comp)} cell(s) with colour {colour}.")
    emit(out, "All rectangle interiors filled: 1-cell holes become 5, 2-cell holes become 7.")
    return out
